<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Raptor: Call of the Shadows — Sector 1 (HTML5 Port)</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      background: #000;
      color: #cfc;
      font-family: monospace;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
      overflow: hidden;
    }
    canvas {
      width: min(96vw, 640px);
      image-rendering: pixelated;
      image-rendering: crisp-edges;
      border: 2px solid #262;
      background: #000;
    }
    #status {
      margin-top: 10px;
      font-size: 14px;
    }
    #controls {
      margin-top: 8px;
      font-size: 12px;
      color: #8a8;
    }
  </style>
</head>
<body>
  <canvas id="raptor-canvas" width="320" height="200"></canvas>
  <div id="status">Loading game data...</div>
  <div id="controls">Arrow keys: move &nbsp; Space: fire</div>
  <script type="module" src="js/main.js"></script>
</body>
</html>

