    s.repos = v.getInt32(o + SROFS.repos, true);
    s.flighttype = v.getInt32(o + SROFS.flighttype, true);
    s.numguns = v.getInt32(o + SROFS.numguns, true);
    s.numengs = v.getInt32(o + SROFS.numengs, true);
    s.sfx = v.getInt32(o + SROFS.sfx, true);
    s.song = v.getInt32(o + SROFS.song, true);
    const rd = (off, cnt) => { const a = []; for (let k = 0; k < cnt; k++) a.push(v.getInt16(o + off + k * 2, true)); return a; };
    s.shoot_type = rd(SROFS.shoot_type, 24);
    s.engx = rd(SROFS.engx, 24);
    s.engy = rd(SROFS.engy, 24);
    s.englx = rd(SROFS.englx, 24);
    s.shootx = rd(SROFS.shootx, 24);
    s.shooty = rd(SROFS.shooty, 24);
    s.flightx = rd(SROFS.flightx, 30);
    s.flighty = rd(SROFS.flighty, 30);
    out.push(s);
  }
  return out;
}

