    this.tileDelay = [];
    this.tilepics = null;
    this.tileepics = null;
    this.cur_ship = [];
    this.numbers = [];
    this.sfxName = { 0: 'THEME_FX', 1: 'MON1_FX', 2: 'MON2_FX', 3: 'MON3_FX', 4: 'MON4_FX', 5: 'MON5_FX', 6: 'MON6_FX', 7: 'DAVE_FX', 8: 'EXPLO_FX', 9: 'EXPLO2_FX', 10: 'BONUS_FX', 11: 'CRASH_FX', 12: 'DOOR_FX', 13: 'FLYBY_FX', 14: 'EGRAB_FX', 15: 'GEXPLO_FX', 16: 'GUN_FX', 17: 'JETSND_FX', 18: 'LASER_FX', 19: 'MISSLE_FX', 20: 'SWEP_FX', 21: 'TURRET_FX', 22: 'WARN_FX', 23: 'BOSS_FX', 24: 'JETSND_FX', 25: 'JETSND_FX', 26: 'GUN_FX', 27: 'GUN_FX', 28: 'ESHOT_FX', 29: 'LASER_FX', 30: 'MISSLE_FX', 31: 'ESHOT_FX', 32: 'HIT_FX', 33: 'HIT_FX', 34: 'ESHOT_FX', 35: 'ESHOT_FX' };
    this.sdtable = null;
    this.stable = [];
    this.animlib = [];
  }

  // Audio callback (set by main.js) — triggered SFX. Returns volume-capped call.
  setAudio(audio) { this.audio = audio; }
  playSfx(type) {
