    };
    reg(356, 42, 0, false, false, 0);   // A_LARGE_GROUND_EXPLO1
    reg(637, 35, 0, false, false, 0);   // A_SMALL_GROUND_EXPLO
    reg(501, 7, 0, false, false, 0);     // A_PERSON
    reg(531, 10, 0, false, false, 0);     // A_PLATOON
    reg(485, 12, 2, false, false, 0);     // A_LARGE_AIR_EXPLO
…
  }
