  // Start sector 1 fresh at a wave (0-based).
  startWave(wave) {
    this.wave = wave;
    this.rand = new Rand(1024 * wave);
    this.gl_cnt = 0;
    this.g_flash = 0;
    this.startendwave = EMPTY;
    this.end_wave = false;
    this.draw_player = true;
    this.fadeflag = false;
    this.init_flag = true;
    this.fadeIn = 64;
    this.playerx = PLAYERINITX;
    this.playery = PLAYERINITY;
    this.player_cx = this.playerx + 16;
    this.player_cy = this.playery + 16;
    this.playerpic = 4;
    this.g_addx = 0;
    this.g_addy = 0;
    this.pauseControl = false;
    this.dead = false;
    this.over = false;
    this.shots = [];
    this.eshots = [];
    this.enemies = [];
    this.anims = [];
    this.bonuses = [];
    this.tileExplosions = [];
    this.tileDelay = [];
