// Start sector 1 fresh at a wave (0-based).
startWave(wave) {
  this.wave = wave;
  this.rand = new Rand(1024 * wave);
  this.gl_cnt = 0;
  this.g_flash = 0;
  this.startendwave = EMPTY;
  this.end_wave = false;
  this.draw_player = true;
  this.fadeflag = false;
  this.init_flag = true;
  this.fadeIn = 64;
  this.playerx = PLAYERINITX;
  this.playery = PLAYERINITY;
  this.player_cx = this.playerx + 16;
  this.player_cy = this.playery + 16;
  this.playerpic = 4;
  this.g_addx = 0;
  this.g_addy = 0;
  this.pauseControl = false;
  this.dead = false;
  this.over = false;
  this.shots = [];
  this.eshots = [];
  this.enemies = [];
  this.anims = [];
  this.bonuses = [];
  this.tileExplosions = [];
  this.tileDelay = [];
  this.shotCooldown = this.shotCooldown.map(() => 0);
  this.loadMap(wave);
  this.tileSetup();
  this.enemyLoad();
  this.buf.fill(0);
}

loadMap(wave) {
  const name = 'MAP' + (wave + 1) + 'G1_MAP';
  const map = this.glb1.raw(name);
  const v = new DataView(map.buffer, map.byteOffset, map.byteLength);
  this.ml = {
    sizerec: v.getUint32(0, true),
    spriteoff: v.getUint32(4, true),
    numsprites: v.getInt32(8, true),
  };
  // map grid: MAZEDATA[1350] { SHORT flats; SHORT fgame }
  this.mapGrid = [];
  for (let i = 0; i < MAP_SIZE; i++) {
    this.mapGrid.push({
      flats: v.getUint16(12 + i * 4, true),
      fgame: v.getUint16(12 + i * 4 + 2, true),
    });
  }
  this.csprite = [];
  const base = 12 + MAP_SIZE * 4;
  for (let i = 0; i < this.ml.numsprites; i++) {
    const o = base + i * 24;
    this.csprite.push({
      link: v.getInt32(o, true),
      slib: v.getInt32(o + 4, true),
      x: v.getInt32(o + 8, true),
      y: v.getInt32(o + 12, true),
      game: v.getInt32(o + 16, true),
      level: v.getUint32(o + 20, true),
    });
  }
  // flat lib (game 0 = FLATSG1_ITM)
  const flats = this.glb1.raw('FLATSG1_ITM');
  const fv = new DataView(flats.buffer, flats.byteOffset, flats.byteLength);
  this.flatlib = [];
  for (let i = 0; i < Math.floor(flats.length / 8); i++) {
    this.flatlib.push({
      linkflat: fv.getInt32(i * 8, true),
      bonus: fv.getInt16(i * 8 + 4, true),
      bounty: fv.getInt16(i * 8 + 6, true),
    });
  }
  // sprite lib (game 0 = SPRITE1_ITM)
  this.spriteLib = parseSpriteLib(this.glb1.raw('SPRITE1_ITM'));
  this.startflat = 863 + 1; // STARTG1TILES + 1
  // resolve sprite item ids by name
  for (const s of this.spriteLib) {
    if (s.iname) {
      const it = this.glb1.find(s.iname);
      if (it) s.item = it.index;
    }
  }
}

tileSetup() {
  this.tilePos = (MAP_ROWS - MAP_ONSCREEN) * MAP_COLS;
  this.tileYoff = 200 - (MAP_ONSCREEN * MAP_BLOCKSIZE);
  this.scroll_flag = true;
  this.last_tile = false;
  this.tileHits.fill(0);
  this.tileDead.fill(0);
  this.tilepics = new Uint32Array(MAP_SIZE);
  this.tileepics = new Uint32Array(MAP_SIZE);
  for (let loop = 0; loop < MAP_SIZE; loop++) {
    const game = 0;
    const flatsIdx = this.mapGrid[loop].flats;
    const lib = this.flatlib[flatsIdx] || { linkflat: 0, bonus: 0, bounty: 0 };
    const item = this.startflat + flatsIdx;
    const eitem = this.startflat + lib.linkflat;
    this.tilepics[loop] = item;
