  const height = [5, 10][frame % 2];
  iy -= height - 1;
  if (iy + height < 0 || iy >= SCREENHEIGHT) return;
  if (ix + width < 0 || ix >= SCREENWIDTH) return;
  const addx = Math.floor((8 << 16) / height);
  let curs = addx * (height - 1);
  for (let loop = 0; loop < height; loop++) {
    const y = iy + loop;
    if (y < 0 || y >= SCREENHEIGHT) { curs -= addx; continue; }
    let num = curs >> 16;
    if (num < 0) num = 0; if (num > 7) num = 7;
    this.shadeRect(this.buf, ix, y, width, this.stable[num]);
    curs -= addx;
  }
}

flameDown(ix, iy, width, frame) {
  const height = [8, 12][frame % 2];
  if (iy + height < 0 || iy >= SCREENHEIGHT) return;
  if (ix + width < 0 || ix >= SCREENWIDTH) return;
  let curs = 0;
  const addx = Math.floor((8 << 16) / height);
  for (let loop = 0; loop < height; loop++) {
    const y = iy + loop;
    if (y < 0 || y >= SCREENHEIGHT) { curs += addx; continue; }
    let num = curs >> 16;
    if (num < 0) num = 0; if (num > 7) num = 7;
    this.shadeRect(this.buf, ix, y, width, this.stable[num]);
    curs += addx;
  }
}

shadeRect(buf, x, y, len, table) {
  if (x < 0) { len += x; x = 0; }
  if (x + len > SCREENWIDTH) len = SCREENWIDTH - x;

