  // Start sector 1 fresh at a wave (0-based).
  startWave(wave) {
    this.wave = wave;
    this.rand = new Rand(1024 * wave);
    this.gl_cnt = 0;
    this.g_flash = 0;
    this.startendwave = EMPTY;
    this.end_wave = false;
    this.draw_player = true;
    this.fadeflag = false;
    this.init_flag = true;
    this.fadeIn = 64;
    this.playerx = PLAYERINITX;
    this.playery = PLAYERINITY;
    this.player_cx = this.playerx + 16;
    this.player_cy = this.playery + 16;
    this.playerpic = 4;
    this.g_addx = 0;
    this.g_addy = 0;
    this.pauseControl = false;
    this.dead = false;
    this.over = false;
    this.shots = [];
    this.eshots = [];
    this.enemies = [];
    this.anims = [];
    this.bonuses = [];
    this.tileExplosions = [];
    this.tileDelay = [];
    this.shotCooldown = this.shotCooldown.map(() => 0);
    this.loadMap(wave);
    this.tileSetup();
    this.enemyLoad();
    this.buf.fill(0);
  }

  loadMap(wave) {
    const name = 'MAP' + (wave + 1) + 'G1_MAP';
    const map = this.glb1.raw(name);
    const v = new DataView(map.buffer, map.byteOffset, map.byteLength);
    this.ml = {
      sizerec: v.getUint32(0, true),
      spriteoff: v.getUint32(4, true),
      numsprites: v.getInt32(8, true),
    };
    // map grid: MAZEDATA[1350] { SHORT flats; SHORT fgame }
    this.mapGrid = [];
    for (let i = 0; i < MAP_SIZE; i++) {
      this.mapGrid.push({
        flats: v.getUint16(12 + i * 4, true),
        fgame: v.getUint16(12 + i * 4 + 2, true),
      });
    }
    this.csprite = [];
    const base = 12 + MAP_SIZE * 4;
    for (let i = 0; i < this.ml.numsprites; i++) {
      const o = base + i * 24;
      this.csprite.push({
        link: v.getInt32(o, true),
        slib: v.getInt32(o + 4, true),
        x: v.getInt32(o + 8, true),
        y: v.getInt32(o + 12, true),
        game: v.getInt32(o + 16, true),
        level: v.getUint32(o + 20, true),
      });
    }
    // flat lib (game 0 = FLATSG1_ITM)
    const flats = this.glb1.raw('FLATSG1_ITM');
    const fv = new DataView(flats.buffer, flats.byteOffset, flats.byteLength);
    this.flatlib = [];
    for (let i = 0; i < Math.floor(flats.length / 8); i++) {
      this.flatlib.push({
        linkflat: fv.getInt32(i * 8, true),
        bonus: fv.getInt16(i * 8 + 4, true),
        bounty: fv.getInt16(i * 8 + 6, true),
      });
    }
    // sprite lib (game 0 = SPRITE1_ITM)
    this.spriteLib = parseSpriteLib(this.glb1.raw('SPRITE1_ITM'));
    this.startflat = 863 + 1; // STARTG1TILES + 1
    // resolve sprite item ids by name
    for (const s of this.spriteLib) {
      if (s.iname) {
        const it = this.glb1.find(s.iname);
        if (it) s.item = it.index;
      }
    }
  }

  tileSetup() {
    this.tilePos = (MAP_ROWS - MAP_ONSCREEN) * MAP_COLS;
    this.tileYoff = 200 - (MAP_ONSCREEN * MAP_BLOCKSIZE);
    this.scroll_flag = true;
    this.last_tile = false;
    this.tileHits.fill(0);
    this.tileDead.fill(0);
    this.tilepics = new Uint32Array(MAP_SIZE);
    this.tileepics = new Uint32Array(MAP_SIZE);
    for (let loop = 0; loop < MAP_SIZE; loop++) {
      const game = 0;
      const flatsIdx = this.mapGrid[loop].flats;
      const lib = this.flatlib[flatsIdx] || { linkflat: 0, bonus: 0, bounty: 0 };
      const item = this.startflat + flatsIdx;
      const eitem = this.startflat + lib.linkflat;
      this.tilepics[loop] = item;
      this.tileepics[loop] = eitem;
      this.tileHits[loop] = (eitem !== item) ? lib.bonus : 1;
    }
  }

  enemyLoad() {
    this.numships = 0; this.numboss = 0; this.end_waveflag = false;
    this.cur_enemy = 0;
    this.cur_visable = 0;
    this.boss_sound = false;
    this.enemies = [];
    // normal difficulty: easy + med
    this.cur_diff = EB_EASY_LEVEL | EB_MED_LEVEL;
    for (let loop = 0; loop < this.csprite.length; loop++) {
      const curfld = this.csprite[loop];
      let lvl = curfld.level;
      if (lvl === 0) lvl = 1; else if (lvl === 1) lvl = 2; else if (lvl === 2) lvl = 4;
      else if (lvl === E_EASY_LEVEL) lvl = EB_EASY_LEVEL;
      else if (lvl === E_MED_LEVEL) lvl = EB_MED_LEVEL;
      else if (lvl === E_HARD_LEVEL) lvl = EB_HARD_LEVEL;
      else lvl = EB_NOT_USED;
      curfld.level = lvl;
      if (!(lvl & this.cur_diff)) curfld.level = EB_NOT_USED;
      const lib = this.spriteLib[curfld.slib];
      if (!lib || !lib.iname) curfld.level = EB_NOT_USED;
    }
  }

  // -------------------------------------------------------------------------
  // Objects
  // -------------------------------------------------------------------------
  objsUse(type) {
    if (type === S_FORWARD_GUNS) this.shootForwardGuns();
  }

  shootForwardGuns() {
    if (this.shotCooldown[S_FORWARD_GUNS] > 0) return false;
    this.shotCooldown[S_FORWARD_GUNS] = 2;
    this.g_flash = 7;
    this.playSfx(16 /* FX_GUN */);
    // twin shots
    const o1 = [1, 3, 5, 6, 5, 3, 1][this.playerpic];
    this.spawnShot(S_FORWARD_GUNS, this.player_cx + o1, this.player_cy, this.rand.random(4));
    this.spawnShot(S_FORWARD_GUNS, this.player_cx - o1 - 1, this.player_cy, this.rand.random(4));
    return true;
  }

  spawnShot(type, x, y, curframe) {
    this.shots.push({
      type, x, y, curframe, speed: 8,
      move: { x, y, x2: x, y2: 0 }, done: false, doneflag: false,
      startx: this.player_cx, starty: this.player_cy,
    });
  }

  shotDamage(type) {
    switch (type) {
      case S_FORWARD_GUNS: return 1;
      default: return 1;
    }
  }

  objEnergy() { return this.energy; }
  subEnergy(amt) {
    if (this.godmode) return;
    if (this.startendwave !== EMPTY) return;
    if (this.super > 0) {
      this.super -= amt;
      if (this.super < 0) this.super = 0;
    } else {
      this.energy -= amt;
      if (this.energy < 0) this.energy = 0;
    }
    this.g_oldshield = EMPTY;
  }

  // -------------------------------------------------------------------------
  // Player movement
  // -------------------------------------------------------------------------
  movePlayer() {
    if (this.pauseControl) { this.g_addx = 0; this.g_addy = 0; }
    const oldx = this.playerx;
    if (!this.pauseControl) {
      const k = this.keys;
      if (k.left || k.right) {
        if (k.left) {
          if (this.g_addx >= 0) this.g_addx = -1;
          this.g_addx--;
          if (-this.g_addx > MAX_ADDX) this.g_addx = -MAX_ADDX;
        } else {
          if (this.g_addx <= 0) this.g_addx = 1;
          this.g_addx++;
          if (this.g_addx > MAX_ADDX) this.g_addx = MAX_ADDX;
        }
      } else if (this.g_addx !== 0) {
        this.g_addx = Math.trunc(this.g_addx / 2);
      }
      if (k.up || k.down) {
        if (k.up) {
          if (this.g_addy >= 0) this.g_addy = -1;
          this.g_addy--;
          if (-this.g_addy > MAX_ADDY) this.g_addy = -MAX_ADDY;
        } else {
          if (this.g_addy <= 0) this.g_addy = 1;
          this.g_addy++;
          if (this.g_addy > MAX_ADDY) this.g_addy = MAX_ADDY;
        }
      } else if (this.g_addy !== 0) {
        this.g_addy = Math.trunc(this.g_addy / 2);
      }
    }
    this.playerx += this.g_addx;
    this.playery += this.g_addy;
    if (this.startendwave === EMPTY) {
      if (this.playery < MINPLAYERY) { this.playery = MINPLAYERY; this.g_addy = 0; }
      else if (this.playery > MAXPLAYERY) { this.playery = MAXPLAYERY; this.g_addy = 0; }
      if (this.playerx < PLAYERMINX) { this.playerx = PLAYERMINX; this.g_addx = 0; }
      else if (this.playerx + PLAYERWIDTH > PLAYERMAXX) { this.playerx = PLAYERMAXX - PLAYERWIDTH; this.g_addx = 0; }
    }
    let delta = Math.abs(this.playerx - oldx) >> 2;
    if (delta > 3) delta = 3;
    if (this.playerx < oldx) {
      if (this.playerpic < this.playerbasepic + delta) this.playerpic++;
    } else if (this.playerx > oldx) {
      if (this.playerpic > this.playerbasepic - delta) this.playerpic--;
    } else {
      if (this.playerpic > this.playerbasepic) this.playerpic--;
      else if (this.playerpic < this.playerbasepic) this.playerpic++;
    }
    this.player_cx = this.playerx + 16;
    this.player_cy = this.playery + 16;
  }

  forceMovePlayer(x, y) {
    this.playerx += x;
    this.playery += y;
    if (this.playery < MINPLAYERY) this.playery = MINPLAYERY;
    if (this.playery > MAXPLAYERY) this.playery = MAXPLAYERY;
    if (this.playerx < PLAYERMINX) this.playerx = PLAYERMINX;
    if (this.playerx + PLAYERWIDTH > PLAYERMAXX) this.playerx = PLAYERMAXX - PLAYERWIDTH;
    this.player_cx = this.playerx + 16;
    this.player_cy = this.playery + 16;
  }

  // -------------------------------------------------------------------------
  // Frame stepping
  // -------------------------------------------------------------------------
  frame() {
    this.frameNo++;
    this.movePlayer();

    // fire
    if (this.keys.fire && this.startendwave === EMPTY && !this.over) {
      this.objsUse(S_FORWARD_GUNS);
    }

    if (this.startendwave !== EMPTY) {
      if (this.startendwave === 0) this.end_wave = true;
      this.startendwave--;
    }

    this.gl_cnt++;

    this.tileThink();
    this.enemyThink();
    this.eshotThink();
    this.bonusThink();
    this.shotThink();
    this.animThink();

    // draw
    this.buf.fill(0);
    this.tileDisplay();

    // ground shadows
    for (const e of this.enemies) if (e.groundflag && e.lib.shadow) this.drawGroundShadow(e);
    // ground enemies
    for (const e of this.enemies) if (e.groundflag) putSprite(this.buf, this.getItem(e.item), e.x, e.y);
    // ship shadow (air)
    if (this.draw_player) drawShadow(this.buf, this.getItem(this.cur_ship[this.playerpic + this.g_flash]), this.playerx, this.playery, this.sdtable);
    // ground anims
    for (const a of this.anims) if (a.groundflag === 0) this.drawAnim(a);
    // air enemies
    for (const e of this.enemies) if (!e.groundflag) {
      putSprite(this.buf, this.getItem(e.item), e.x, e.y);
      if (e.lib.numengs > 0) {
        const frame = e.eframe ^= 1;
        for (let i = 0; i < e.lib.numengs; i++) {
          this.flameUp(e.x + e.lib.engx[i], e.y + e.lib.engy[i], e.lib.englx[i], frame);
        }
      }
    }
    // player shots
    for (const s of this.shots) putSprite(this.buf, s.pic, s.x, s.y);
    // bonuses
    for (const b of this.bonuses) {
      if (!b.dflag) {
        putSprite(this.buf, this.getItem(b.item), b.bx, b.by);
        putShadeShape(this.buf, this.getItem(this.glowItem(b.curglow)), b.gx, b.gy, this.stable[4]);
      } else {
        putSprite(this.buf, this.getItem(5 + 1), b.bx, b.by);
      }
    }
    // sky anims
    for (const a of this.anims) if (a.groundflag === 1) this.drawAnim(a);
    // ship
    if (this.draw_player) {
      this.flameDown(this.player_cx + -this.o_engine[this.playerpic] - 3, this.player_cy + 15, 4, this.gl_cnt % 2);
      this.flameDown(this.player_cx + this.o_engine[this.playerpic] - 2, this.player_cy + 15, 4, this.gl_cnt % 2);
      putSprite(this.buf, this.getItem(this.cur_ship[this.playerpic + this.g_flash]), this.playerx, this.playery);
      this.g_flash = 0;
    }
    // high anims
    for (const a of this.anims) if (a.groundflag === 2) this.drawAnim(a);
    // enemy shots
    for (const s of this.eshots) this.drawEshot(s);

    this.displayStats();

    // fade-in handling
    if (this.init_flag) {
      this.init_flag = false;
    }

    // palette rotation (after fade-in completes)
    if (!this.fadeflag) {
      this.paletteStuff();
    }
  }

