    putSprite(this.buf, s.pic, s.x, s.y);
  }

  // -------------------------------------------------------------------------
  // Tiles
  // -------------------------------------------------------------------------
  tileThink() {
    // tile damage processing
    for (let i = 0; i < this.tileDelay.length; i++) {
      const td = this.tileDelay[i];
      if (td.mapspot - this.tilePos > MAP_ONSCREEN * MAP_COLS) {
        this.tileDelay.splice(i, 1); i--;
        continue;
      }
      if (td.frames < 0) {
        this.tileDelay.splice(i, 1); i--;
        continue;
      }
      td.frames--;
    }
  }

  tileDisplay() {
    for (let loopy = 0; loopy < MAP_ONSCREEN; loopy++) {
      const y = this.tileYoff + loopy * MAP_BLOCKSIZE;
      for (let loopx = 0; loopx < MAP_COLS; loopx++) {
        const mapspot = this.tilePos + loopy * MAP_COLS + loopx;
        const x = MAP_LEFT + loopx * MAP_BLOCKSIZE;
        const item = this.tilepics[mapspot];
        this.tilePut(this.getItem(item), x, y);
      }
    }
    this.tileYoff++;
    if (this.tileYoff > 0) {
      if (this.last_tile && this.tileYoff >= 0) {
        this.tileYoff = 0;
        this.scroll_flag = false;
      } else {
        this.tileYoff -= MAP_BLOCKSIZE;
        this.tilePos -= MAP_COLS;
      }
      if (this.tilePos <= 0) { this.tilePos = 0; this.last_tile = true; }
    }
  }

  tilePut(pic, x, y) {
    if (y + 32 <= 0 || y >= SCREENHEIGHT) return;
    let sy = y, ly = 32;
    let sOff = 0;
    if (y < 0) { sOff = -y * 32; ly += y; y = 0; }
    if (y + ly > SCREENHEIGHT) ly = SCREENHEIGHT - y;
    for (let row = 0; row < ly; row++) {
      const src = 20 + sOff + row * 32;
      const dst = (y + row) * SCREENWIDTH + x;
      if (x >= 0 && x + 32 <= SCREENWIDTH) {
        this.buf.set(pic.subarray(src, src + 32), dst);
      } else {
        for (let c = 0; c < 32; c++) {
          const dx = x + c;
          if (dx >= 0 && dx < SCREENWIDTH) this.buf[dst + c] = pic[src + c];
        }
      }
    }
    void sy;
  }

  tileIsHit(damage, x, y) {
    for (let i = 0; i < MAP_ONSCREEN * MAP_COLS; i++) {
      const tsX = MAP_LEFT + (i % MAP_COLS) * 32;
      const tsY = this.tileYoff + Math.floor(i / MAP_COLS) * 32;
      if (x >= tsX && x < tsX + 32 && y >= tsY && y < tsY + 32) {
        const mapspot = this.tilePos + i;
        if (this.tileepics[mapspot] !== this.tilepics[mapspot]) {
          this.tileHits[mapspot] -= damage;
          return true;
        }
      }
    }
    return false;
  }

  // -------------------------------------------------------------------------
  // Enemies
  // -------------------------------------------------------------------------
  enemyThink() {
    if (this.boss_sound) {
      // play boss hum occasionally
    }
    const tiley = Math.floor(this.tilePos / MAP_COLS) - 3;
    if (!this.end_waveflag) {
      while (this.cur_enemy < this.csprite.length && this.csprite[this.cur_enemy].y === tiley) {
        let spawnAny = false;
        for (;;) {
          const old_enemy = this.cur_enemy;
          if (this.csprite[this.cur_enemy].level !== EB_NOT_USED) {
            this.enemyAdd(this.csprite[this.cur_enemy]);
            spawnAny = true;
          }
          if (this.cur_enemy === this.csprite.length - 1) { this.end_waveflag = true; break; }
          this.cur_enemy++;
          const link = this.csprite[old_enemy].link;
          if (link === EMPTY || link === 1) break;
        }
        if (this.end_waveflag) break;
      }
    }

    this.cur_visable = 0;
    for (let ei = 0; ei < this.enemies.length; ei++) {
      const sprite = this.enemies[ei];
      const curlib = sprite.lib;
      if (curlib.num_frames > 1) {
        sprite.item = curlib.item + sprite.curframe;
        if (sprite.frame_rate < 1) {
          sprite.frame_rate = curlib.frame_rate;
          if (sprite.anim_on) {
            sprite.curframe++;
            if (sprite.curframe >= sprite.num_frames) {
              sprite.curframe -= curlib.rewind;
              switch (curlib.animtype) {
                case GANIM_NORM: break;
                case GANIM_SHOOT: sprite.anim_on = false; sprite.shoot_on = true; break;
                case GANIM_MULTI:
                  if (sprite.multi === 0) { sprite.num_frames = curlib.num_frames; sprite.multi = 1; }
                  else if (sprite.multi === 1) { sprite.shoot_on = true; sprite.multi = 2; }
                  break;
              }
            }
          }
        } else {
          sprite.frame_rate--;
        }
        if (sprite.countdown < 1) {
          switch (curlib.animtype) {
            case GANIM_NORM: sprite.shoot_on = true; break;
            case GANIM_SHOOT: sprite.anim_on = true; break;
            case GANIM_MULTI: if (sprite.multi === 2) sprite.multi = 0; break;
          }
        } else {
          sprite.countdown -= curlib.movespeed;
        }
      } else {
        if (sprite.countdown < 1) { sprite.countdown = -1; sprite.shoot_on = true; }
        else sprite.countdown -= curlib.movespeed;
      }

      const move = sprite.move;
      let speed;
      switch (curlib.flighttype) {
        case F_REPEAT:
        case F_LINEAR:
          sprite.x = move.x; sprite.y = move.y;
          sprite.x2 = sprite.x + sprite.width - 1;
          sprite.y2 = sprite.y + sprite.height - 1;
          speed = curlib.movespeed;
          speed = this.moveEobj(move, speed);
          if (move.done) {
            move.x = move.x2; move.y = move.y2;
            if (curlib.flighttype === F_REPEAT) {
              move.x2 = sprite.sx + curlib.flightx[sprite.movepos];
              move.y2 = sprite.sy + curlib.flighty[sprite.movepos];
              this.initMobj(move); this.moveMobj(move);
              speed = this.moveEobj(move, speed);
              if (sprite.edir === E_FORWARD) {
                sprite.movepos++;
                if (sprite.movepos >= curlib.numflight) { sprite.edir = E_BACKWARD; sprite.movepos = curlib.numflight - 1; }
              } else {
                sprite.movepos--;
                if (sprite.movepos <= curlib.repos) { sprite.edir = E_FORWARD; sprite.movepos = curlib.repos; }
              }
            } else {
              move.x2 = sprite.sx + curlib.flightx[sprite.movepos];
              move.y2 = sprite.sy + curlib.flighty[sprite.movepos];
              this.initMobj(move); this.moveMobj(move);
              speed = this.moveEobj(move, speed);
              sprite.movepos++;
              if (sprite.movepos > curlib.numflight) sprite.doneflag = true;
            }
          }
          break;
        case F_KAMI:
          sprite.x = move.x; sprite.y = move.y;
          sprite.x2 = sprite.x + sprite.width - 1;
          sprite.y2 = sprite.y + sprite.height - 1;
          speed = curlib.movespeed;
          speed = this.moveEobj(move, speed);
          if (sprite.kami === KAMI_END) {
            if (move.y > 201) sprite.doneflag = true;
            if (move.x > 320 + sprite.hlx) sprite.doneflag = true;
            if (move.y + sprite.width < 0) sprite.doneflag = true;
            if (move.x + sprite.width < 0) sprite.doneflag = true;
          }
          if (move.done && sprite.kami !== KAMI_END) {
            move.x = move.x2; move.y = move.y2;
            sprite.x2 = sprite.x + sprite.width - 1;
            sprite.y2 = sprite.y + sprite.height - 1;
            if (sprite.kami === KAMI_CHASE) {
              move.x2 = this.player_cx; move.y2 = this.player_cy;
              sprite.kami = KAMI_END;
            } else {
              move.x2 = sprite.sx + curlib.flightx[sprite.movepos];
              move.y2 = sprite.sy + curlib.flighty[sprite.movepos];
            }
            this.initMobj(move); this.moveMobj(move);
            speed = this.moveEobj(move, speed);
            if (sprite.movepos < curlib.numflight - 1) sprite.movepos++;
            else if (sprite.kami === KAMI_FLY) sprite.kami = KAMI_CHASE;
          }
          break;
        case F_GROUND:
          if (this.scroll_flag) sprite.y++;
          if (sprite.y > sprite.move.y2) sprite.doneflag = true;
          sprite.x2 = sprite.x + sprite.width - 1;
          sprite.y2 = sprite.y + sprite.height - 1;
          break;
        case F_GROUNDRIGHT:
          if (this.scroll_flag) sprite.y++;
          if (sprite.y >= 0) {
            sprite.x += curlib.movespeed;
            if (sprite.x > sprite.move.x2) sprite.doneflag = true;
            else if (sprite.y > sprite.move.y2) sprite.doneflag = true;
          }
          sprite.x2 = sprite.x + sprite.width - 1;
          sprite.y2 = sprite.y + sprite.height - 1;
          break;
        case F_GROUNDLEFT:
          if (this.scroll_flag) sprite.y++;
          if (sprite.y >= 0) {
            sprite.x -= curlib.movespeed;
            if (sprite.x < sprite.move.x2) sprite.doneflag = true;
            else if (sprite.y > sprite.move.y2) sprite.doneflag = true;
          }
          sprite.x2 = sprite.x + sprite.width - 1;
          sprite.y2 = sprite.y + sprite.height - 1;
          break;
      }

      // shooting
      if (sprite.shoot_on) {
        if (sprite.shootagain === NORM_SHOOT) {
          sprite.shootflag--;
          if (sprite.shootflag < 0) {
            sprite.shootflag = curlib.shotspace;
            if (!sprite.shoot_disable) {
              for (let loop = 0; loop < curlib.numguns; loop++) this.eshotShoot(sprite, loop);
            }
            sprite.shootcount--;
            if (sprite.shootcount < 1) sprite.shootagain = curlib.shootframe;
          }
        } else if (sprite.shootagain === START_SHOOT) {
          sprite.shootagain = NORM_SHOOT;
          sprite.shootcount = curlib.shootcnt;
          sprite.shootflag = curlib.shotspace;
        } else {
          sprite.shootagain--;
        }
      }

      if (sprite.doneflag) {
        this.enemies.splice(ei, 1); ei--;
        this.numships--;
        if (this.end_waveflag && this.numships < 1) this.startendwave = END_DURATION;
        continue;
      }

      // collision with player
      if (!sprite.groundflag) {
        if (this.player_cx > sprite.x && this.player_cx < sprite.x2 && this.player_cy > sprite.y && this.player_cy < sprite.y2) {
          sprite.hits -= PLAYERWIDTH >> 1;
          const suben = sprite.width > sprite.height ? sprite.width : sprite.height;
          this.subEnergy(suben >> 2, 'ram');
          this.startAnim(A_SMALL_AIR_EXPLO, this.player_cx + (this.rand.random(8) - 4), this.player_cy + (this.rand.random(8) - 4));
          this.playSfx(11 /* FX_CRASH */);
        }
      }

      if (sprite.hits <= 0) {
        this.score += curlib.money;
        this.playSfx(8 /* FX_AIREXPLO */);
        const ex = sprite.x + sprite.hlx, ey = sprite.y + sprite.hly;
        switch (curlib.exptype) {
          case EXP_ENERGY:
            this.startAnim(A_ENERGY_AIR_EXPLO, ex, ey);
            this.bonusAdd(S_ITEMBUY6, sprite.x, sprite.y);
