          case EXP_AIRSMALL1: this.startAnim(A_MED_AIR_EXPLO, ex, ey); break;
          case EXP_AIRSMALL2: this.startAnim(A_MED_AIR_EXPLO2, ex, ey); break;
          case EXP_AIRMED: this.startAnim(A_LARGE_AIR_EXPLO, ex, ey); break;
          case EXP_AIRLARGE:
            this.startAnim(A_LARGE_AIR_EXPLO, ex, ey);
            {
              const area = (sprite.width >> 4) * (sprite.height >> 4);
              for (let loop = 0; loop < area; loop++) {
                const x = sprite.x + this.rand.random(sprite.width);
                const y = sprite.y + this.rand.random(sprite.height);
                if (loop & 1) this.startAnim(A_MED_AIR_EXPLO, x, y);
                else this.startAAnim(A_MED_AIR_EXPLO2, x, y);
              }
            }
            break;
          case EXP_GRDSMALL: this.startAnim(A_SMALL_GROUND_EXPLO, ex, ey); break;
          case EXP_GRDMED: {
            const x = sprite.x + this.rand.random(sprite.width);
            const y = sprite.y + this.rand.random(sprite.height);
            if (this.rand.random(2) === 0) this.startAnim(A_GROUND_SPARKLE, x, y);
            else this.startAnim(A_GROUND_FLARE, x, y);
            this.startAnim(A_LARGE_GROUND_EXPLO1, ex, ey);
            break;
          }
          case EXP_GRDLARGE:
            this.startAnim(A_LARGE_GROUND_EXPLO1, ex, ey);
            {
              const area = (sprite.width >> 4) * (sprite.height >> 4);
              for (let loop = 0; loop < area; loop++) {
                const x = sprite.x + this.rand.random(sprite.width);
                const y = sprite.y + this.rand.random(sprite.height);
                if (this.rand.random(2) === 0) this.startAnim(A_GROUND_FLARE, x, y);
                else this.startAnim(A_GROUND_SPARKLE, x, y);
                this.startAnim(A_SMALL_GROUND_EXPLO, x, y);
              }
            }
            break;
          case EXP_BOSS:
            this.startAnim(A_LARGE_AIR_EXPLO, ex, ey);
            {
              const area = (sprite.width >> 4) * (sprite.height >> 4);
              for (let loop = 0; loop < area; loop++) {
                const x = sprite.x + this.rand.random(sprite.width);
                const y = sprite.y + this.rand.random(sprite.height);
                this.startAAnim(A_GROUND_FLARE, x, y);
                if (loop & 1) this.startAnim(A_LARGE_AIR_EXPLO, x, y);
                else this.startAnim(A_MED_AIR_EXPLO2, x, y);
              }
            }
            break;
          case EXP_PERSON: this.startAnim(A_PERSON, ex, ey); break;
          case EXP_PLATOON: this.startAnim(A_PLATOON, ex, ey); break;
        }
        if (curlib.bonus !== EMPTY) this.bonusAdd(curlib.bonus, sprite.x, sprite.y);
        if (curlib.bossflag) this.numboss--;
        this.enemies.splice(ei, 1); ei--;
        this.numships--;
        if (this.end_waveflag && this.numships < 1) this.startendwave = END_DURATION;
        continue;
      }

      const y = sprite.y + sprite.height;
      if (y > 0 && sprite.y < 200) {
        const x = sprite.x + sprite.width;
        if (x > 0 && sprite.x < 320) this.cur_visable++;
      }
    }
  }

