  // MOVEOBJ helpers (MoveMobj / MoveEobj)
  initMobj(m) {
    m.done = false; m.addx = 1; m.addy = 1;
    m.delx = m.x2 - m.x; m.dely = m.y2 - m.y;
    if (m.delx < 0) { m.delx = -m.delx; m.addx = -m.addx; }
    if (m.dely < 0) { m.dely = -m.dely; m.addy = -m.addy; }
    if (m.delx >= m.dely) { m.err = -(m.dely >> 1); m.maxloop = m.delx + 1; }
    else { m.err = m.delx >> 1; m.maxloop = m.dely + 1; }
  }
  moveMobj(m) {
    if (m.maxloop === 0) { m.done = true; return; }
    if (m.delx >= m.dely) {
      m.x += m.addx; m.err += m.dely;
      if (m.err > 0) { m.y += m.addy; m.err -= m.delx; }
    } else {
      m.y += m.addy; m.err += m.delx;
      if (m.err > 0) { m.x += m.addx; m.err -= m.dely; }
    }
    m.maxloop--;
  }
  moveEobj(m, speed) {
    if (speed === 0) return 0;
    if (m.delx >= m.dely) {
      while (speed) {
        speed--; m.maxloop--;
        if (m.maxloop === 0) { m.done = true; return speed; }
        m.x += m.addx; m.err += m.dely;
        if (m.err > 0) { m.y += m.addy; m.err -= m.delx; }
      }
    } else {
      while (speed) {
        speed--; m.maxloop--;
        if (m.maxloop === 0) { m.done = true; return speed; }
        m.y += m.addy; m.err += m.delx;
        if (m.err > 0) { m.x += m.addx; m.err -= m.dely; }
      }
    }
    if (m.maxloop < 1) m.done = true;
    return speed;
  }

  enemyDamage(x, y, damage, groundOnly) {
    for (const e of this.enemies) {
      if (groundOnly && !e.groundflag) continue;
      if (x > e.x && x < e.x2 && y > e.y && y < e.y2) { e.hits -= damage; return true; }
    }
    return false;
  }
  enemyDamageAll(x, y, damage) { return this.enemyDamage(x, y, damage, false); }
  enemyDamageAir(x, y, damage) {
    for (const e of this.enemies) {
      if (e.groundflag) continue;
      if (x > e.x && x < e.x2 && y > e.y && y < e.y2) { e.hits -= damage; return true; }
    }
    return false;
  }
  enemyDamageGround(x, y, damage) { return this.enemyDamage(x, y, damage, true); }

  // -------------------------------------------------------------------------
  // Player shots
  // -------------------------------------------------------------------------
  shotThink() {
    for (let i = 0; i < this.shotCooldown.length; i++) if (this.shotCooldown[i] > 0) this.shotCooldown[i]--;
    const NMSHOT = 451;
    for (let si = 0; si < this.shots.length; si++) {
      const s = this.shots[si];
      s.pic = this.getItem(NMSHOT + s.curframe);
      // move up
      if (s.speed < 16) s.speed++;
      s.curframe++;
      if (s.curframe >= 4) s.curframe = 0;
      s.move.y -= s.speed;
      s.x = s.move.x;
      s.y = s.move.y;
      if (s.y < 0 || s.y > 200) { this.shots.splice(si, 1); si--; continue; }
      // hit test
      if (this.enemyDamageAll(s.x, s.y, 1)) {
        if (this.rand.random(2)) this.startAnim(A_BLUE_SPARK, s.x, s.y);
        else this.startAnim(A_ORANGE_SPARK, s.x, s.y);
        this.shots.splice(si, 1); si--;
        continue;
      }
      if (this.tileIsHit(1, s.x, s.y)) { this.shots.splice(si, 1); si--; continue; }
    }
  }

  // -------------------------------------------------------------------------
  // Enemy shots
  // -------------------------------------------------------------------------
  eshotShoot(enemy, gunNum) {
    let x = enemy.x + enemy.lib.shootx[gunNum];
    let y = enemy.y + enemy.lib.shooty[gunNum];
    if (x < 0 || x >= 320) return;
    if (y < 0 || y >= 200) return;
    const type = enemy.lib.shoot_type[gunNum];
    const libs = this.eshotLibs();
    const e = {
      type, lib: libs[0], curframe: 0, speed: 0, pos: 0,
      move: { x, y, x2: 0, y2: 0 }, done: false,
      en: enemy, gunNum, x: 0, y: 0, cnt: 0,
    };
    switch (type) {
      case ES_ATPLAYER:
        this.playSfx(28);
        e.lib = libs[1]; e.move.x -= e.lib.xoff; e.move.y -= e.lib.yoff;
        e.move.x2 = this.player_cx; e.move.y2 = this.player_cy; e.speed = 1;
        break;
      case ES_ATDOWN:
        this.playSfx(28);
        e.lib = libs[0]; e.move.x -= e.lib.xoff; e.move.y -= e.lib.yoff;
        e.move.x2 = e.move.x; e.move.y2 = 200; e.speed = e.lib.speed >> 1;
        break;
      case ES_ANGLELEFT:
        this.playSfx(28);
        e.lib = libs[0]; e.move.x -= e.lib.xoff; e.move.y -= e.lib.yoff;
        e.move.x2 = e.move.x - 32; e.move.y2 = e.move.y + 32; e.speed = e.lib.speed >> 1;
        break;
