      s.pic = this.getItem(NMSHOT + s.curframe);
      // move up
      if (s.speed < 16) s.speed++;
      s.curframe++;
      if (s.curframe >= 4) s.curframe = 0;
      s.move.y -= s.speed;
      s.x = s.move.x;
