eshotShoot(enemy, gunNum) {
  let x = enemy.x + enemy.lib.shootx[gunNum];
  let y = enemy.y + enemy.lib.shooty[gunNum];
  if (x < 0 || x >= 320) return;
  if (y < 0 || y >= 200) return;
  const type = enemy.lib.shoot_type[gunNum];
  const libs = this.eshotLibs();
  const e = {
    type, lib: libs[0], curframe: 0, speed: 0, pos: 0,
    move: { x, y, x2: 0, y2: 0 }, done: false,
    en: enemy, gunNum, x: 0, y: 0, cnt: 0,
  };
  switch (type) {
    case ES_ATPLAYER:
      this.playSfx(28);
      e.lib = libs[1]; e.move.x -= e.lib.xoff; e.move.y -= e.lib.yoff;
      e.move.x2 = this.player_cx; e.move.y2 = this.player_cy; e.speed = 1;
      break;
    case ES_ATDOWN:
      this.playSfx(28);
      e.lib = libs[0]; e.move.x -= e.lib.xoff; e.move.y -= e.lib.yoff;
      e.move.x2 = e.move.x; e.move.y2 = 200; e.speed = e.lib.speed >> 1;
      break;
    case ES_ANGLELEFT:
      this.playSfx(28);
      e.lib = libs[0]; e.move.x -= e.lib.xoff; e.move.y -= e.lib.yoff;
      e.move.x2 = e.move.x - 32; e.move.y2 = e.move.y + 32; e.speed = e.lib.speed >> 1;
