      this.playSfx(28);
      e.lib = libs[0]; e.move.x -= e.lib.xoff; e.move.y -= e.lib.yoff;
      e.move.x2 = e.move.x + 32; e.move.y2 = e.move.y + 32; e.speed = e.lib.speed >> 1;
      break;
    case ES_MISSLE:
      this.playSfx(30);
      e.lib = libs[2]; e.move.x -= e.lib.xoff; e.move.y -= e.lib.yoff;
      e.move.x2 = e.move.x; e.move.y2 = 200; e.speed = enemy.speed + 1;
      break;
    case ES_MINES:
      this.playSfx(28);
      e.lib = libs[3]; e.x = e.move.x; e.y = e.move.y;
      e.move.x2 = 320; e.move.y2 = 200; e.speed = 150; e.pos = this.rand.random(16);
      break;
    case ES_LASER:
      this.playSfx(29);
      e.lib = libs[4]; e.move.x -= e.lib.xoff;
      e.move.x2 = e.move.x; e.move.y2 = 200; e.speed = enemy.speed;
      break;
    case ES_PLASMA:
      this.playSfx(31);
      e.lib = libs[5]; e.move.x -= e.lib.xoff;
      e.move.x2 = e.move.x; e.move.y2 = 200; e.speed = 8;
      break;
    case ES_COCONUTS:
      this.playSfx(this.rand.random(6) + 1);
      e.lib = libs[6]; e.move.x -= e.lib.xoff; e.move.y -= e.lib.yoff;
      e.move.x2 = this.player_cx; e.move.y2 = this.player_cy; e.speed = 1;
      break;
  }
  this.initMobj(e.move);
  this.moveSobj(e.move, 1);
  if (e.move.x < 0 || e.move.x >= 320) e.done = true;
  if (e.move.y < 0 || e.move.y >= 200) e.done = true;
  if (!e.done) this.eshots.push(e);
}

_eshotLibs = null;
eshotLibs() {
  if (this._eshotLibs) return this._eshotLibs;
  const mk = (item, num, xoff, yoff, speed, hits) => {
    const h = this.picHeader(this.getItem(item));
    return { item, num_frames: num, xoff: h.width >> 1, yoff: h.height >> 1, speed, hits };
  };
  this._eshotLibs = [
    mk(470, 2, 0, 0, 6, 2),   // LIB_NORMAL
    mk(470, 2, 0, 0, 6, 1),   // LIB_ATPLAY
    mk(468, 2, 0, 0, 10, 4),  // LIB_MISSLE
    mk(465, 2, 0, 0, 0, 16),  // LIB_MINES
    mk(577, 4, 0, 0, 6, 12),  // LIB_LASER
    mk(593, 1, 0, 0, 10, 15), // LIB_PLASMA
    mk(589, 4, 0, 0, 6, 1),    // LIB_COCO
  ];
  return this._eshotLibs;
}

eshotThink() {
  const xpos = [-1, 0, 1, 2, 3, 3, 3, 2, 1, 0, -1, -2, -3, -3, -3, -2];
  const ypos = [-3, -3, -3, -2, -1, 0, 1, 2, 3, 3, 3, 2, 1, 0, -1, -2];
  for (let i = 0; i < this.eshots.length; i++) {
    const shot = this.eshots[i];
    const lib = shot.lib;
    shot.pic = this.getItem(lib.item + (shot.curframe % lib.num_frames));
    shot.curframe++;
    let remove = false;
    if (shot.type === ES_LASER) {
      if (shot.curframe < lib.num_frames) {
        shot.x = shot.en.x + shot.en.lib.shootx[shot.gunNum] - 4;
        shot.y = shot.en.y + shot.en.lib.shooty[shot.gunNum];
        shot.move.y2 = 200;
        const dx = Math.abs(shot.x - this.player_cx);
        if (dx < PLAYERWIDTH / 2 && shot.y < this.player_cy) {
          shot.move.y2 = this.player_cy + this.rand.random(4) - 2;
          this.subEnergy(lib.hits, 'eshot');
        }
      } else remove = true;
    } else {
      if (shot.curframe >= lib.num_frames) shot.curframe = 0;
      if (lib.speed) {
        shot.x = shot.move.x;
        shot.y = shot.move.y;
        this.moveSobj(shot.move, shot.speed);
        if (shot.speed < lib.speed) shot.speed++;
      } else {
        shot.speed--;
        if (shot.speed) {
          shot.x = shot.move.x + xpos[shot.pos];
          shot.y = shot.move.y + ypos[shot.pos];
          shot.move.y++;
          shot.pos++; if (shot.pos >= 16) shot.pos = 0;
        } else {
          remove = true;
          this.startAnim(A_SMALL_AIR_EXPLO, shot.x + 4, shot.y + 4);
        }
      }
      if (shot.y >= 200 || shot.y < 0) remove = true;
      if (shot.x >= 320 || shot.x < 0) remove = true;
      const dx = Math.abs(shot.x - this.player_cx);
      const dy = Math.abs(shot.y - this.player_cy);
      if (dx < PLAYERWIDTH / 2 && dy < PLAYERHEIGHT / 2) {
        this.startAnim(A_SMALL_AIR_EXPLO, shot.x, shot.y);
        remove = true;
        this.subEnergy(lib.hits, 'eshot');
      }
    }
    if (remove) { this.eshots.splice(i, 1); i--; continue; }
    shot.cnt++;
    if (lib.smokeflag && shot.cnt & 1) {
      this.startAAnim(A_SMALL_SMOKE_UP, shot.x + lib.xoff, shot.y);
    }
  }
}

moveSobj(m, speed) {
  if (speed === 0) return 0;
  if (m.delx >= m.dely) {
    while (speed) {
      speed--; m.maxloop--;
      m.x += m.addx; m.err += m.dely;
      if (m.err > 0) { m.y += m.addy; m.err -= m.delx; }
    }
  } else {
    while (speed) {
      speed--; m.maxloop--;
      m.y += m.addy; m.err += m.delx;
      if (m.err > 0) { m.x += m.addx; m.err -= m.dely; }
    }
  }
  if (m.maxloop < 1) m.done = true;
  return speed;
}

