  // -------------------------------------------------------------------------
  // Anims
  // -------------------------------------------------------------------------
  startAnim(handle, x, y) {
    const lib = this.animlib[handle];
    this.anims.push({ lib, x: x - lib.xoff, y: y - lib.yoff, dx: 0, dy: 0, curframe: 0, groundflag: lib.ground, en: null, edone: false });
  }
  startAAnim(handle, x, y) {
    const lib = this.animlib[handle];
    this.anims.push({ lib, x: x - lib.xoff, y: y - lib.yoff, dx: 0, dy: 0, curframe: 0, groundflag: 2, en: null, edone: false });
  }

  animThink() {
    for (let i = 0; i < this.anims.length; i++) {
      const a = this.anims[i];
      const lib = a.lib;
      if (a.curframe >= lib.numframes) { this.anims.splice(i, 1); i--; continue; }
      a.item = lib.item + a.curframe;
      if (lib.playerflag) {
        a.dx = this.player_cx + a.x;
        a.dy = this.player_cy + a.y;
      } else {
        a.dx = a.x; a.dy = a.y;
      }
      if (lib.adir === 1) a.y++;
      else if (lib.adir === 2) a.y--;
      if (lib.ground === 0 && this.scroll_flag) a.y++;
      a.pic = this.getItem(a.item);
      a.curframe++;
    }
  }

  // -------------------------------------------------------------------------
  // Bonuses
  // -------------------------------------------------------------------------
  bonusAdd(type, x, y) {
    if (type >= S_LAST_OBJECT) return;
    if (type === S_ITEMBUY6 && this.energyCount > 9) return;
    this.bonuses.push({
