    });
    if (type === S_ITEMBUY6) this.energyCount = (this.energyCount || 0) + 1;
  }
  energyCount = 0;

  objLib(type) {
    // minimal obj lib for bonus rendering
    const items = [688, 689, 691, 693, 694, 698, 702, 703, 704, 705, 709, 710, 712, 716, 720, 721, 725, 726, 727, 728, 729, 730, 731];
    const frames = [1, 2, 2, 1, 4, 4, 1, 1, 1, 4, 1, 2, 4, 4, 1, 4, 1, 1, 1, 1, 1, 1, 4];
    return { item: items[type] ?? 688, numframes: frames[type] ?? 1 };
  }

  bonusThink() {
    const xpos = [-1, 0, 1, 2, 3, 3, 3, 2, 1, 0, -1, -2, -3, -3, -3, -2];
    const ypos = [-3, -3, -3, -2, -1, 0, 1, 2, 3, 3, 3, 2, 1, 0, -1, -2];
    const gcnt = this.gl_cnt;
    for (let i = 0; i < this.bonuses.length; i++) {
      const b = this.bonuses[i];
      b.item = b.lib.item + b.curframe;
      b.bx = b.x - 8 + xpos[b.pos];
      b.by = b.y - 8 + ypos[b.pos];
      const glowH = this.picHeader(this.getItem(549)).height;
      b.gx = b.x - (16 >> 1) + xpos[b.pos];
      b.gy = b.y - (glowH >> 1) + ypos[b.pos];
      b.y++;
      if (gcnt & 1) {
        b.pos++; if (b.pos >= 16) b.pos = 0;
        b.curframe++; if (b.curframe >= b.lib.numframes) b.curframe = 0;
      }
      b.curglow++; if (b.curglow >= 4) b.curglow = 0;
      const x = this.playerx, x2 = this.playerx + PLAYERWIDTH;
      const y = this.playery, y2 = this.playery + PLAYERHEIGHT;
      if (b.x > x && b.x < x2 && b.y > y && b.y < y2) {
        if (!b.dflag && this.energy > 0) {
          this.playSfx(10);
          if (b.type === S_ENERGY) this.addEnergy(MAX_SHIELD / 4);
          else this.applyBonus(b.type);
          if (b.lib.moneyflag) { b.dflag = true; b.countdown = 50; }
          else { this.bonuses.splice(i, 1); i--; continue; }
        }
      }
      if (b.dflag) {
        b.countdown--;
        if (b.countdown <= 0) { this.bonuses.splice(i, 1); i--; continue; }
      }
      if (b.gy > 200) { this.bonuses.splice(i, 1); i--; continue; }
    }
  }

  applyBonus(type) {
    if (type >= S_ITEMBUY1) { this.score += this.objLib(type).item; return; }
    // weapons not purchasable in our minimal port — just award money
    this.score += 100;
  }
  addEnergy(amt) {
    if (this.energy < MAX_SHIELD) {
      this.energy += amt;
      if (this.energy > MAX_SHIELD) this.energy = MAX_SHIELD;
    }
  }

