      this.startAnim(A_SMALL_AIR_EXPLO, this.playerx + this.rand.random(32), this.playery + this.rand.random(32));
      if (this.startendwave === EMPTY) this.startendwave = END_DURATION;
      if (this.startendwave === END_EXPLODE) {
        this.draw_player = false;
        this.playSfx(8);
        this.playSfx(9);
        this.startAnim(A_LARGE_AIR_EXPLO, this.player_cx, this.player_cy);
        for (let loop = 0; loop < (PLAYERWIDTH * PLAYERHEIGHT) / 2; loop++) {
          const x = this.playerx - 16 + this.rand.random(64);
