        this.deathTimer = 90;
      }
    }

    if (this.startendwave !== EMPTY && shield > 0) {
      if (this.startendwave === END_FLYOFF) {
        this.pauseControl = true;
        this.playSfx(13);
      }
      if (this.startendwave < END_FLYOFF) {
        let x = 0;
        if (this.playerx < 152) x = 8;
        else if (this.playerx > 168) x = -8;
        this.forceMovePlayer(x, -4);
      }
    }

    if (shield <= SHIELD_LOW && !this.godmode && shield > 0) {
      if (this.gl_cnt % 8 === 0) {
        this.blinkflag = !this.blinkflag;
        if (this.blinkflag && this.damage) this.damage--;
      }
      if (this.blinkflag) {
        if (this.damage) {
          const pic = this.getItem(17);
          const h = this.picHeader(pic);
          putSprite(this.buf, pic, (320 - h.width) >> 1, MAP_BOTTOM - 9);
        }
        if (this.startendwave === EMPTY) this.playSfx(22);
        const pic2 = this.getItem(16);
        const h2 = this.picHeader(pic2);
        putSprite(this.buf, pic2, (320 - h2.width) >> 1, MAP_BOTTOM);
      }
    }

    // score
    const s = String(Math.max(0, Math.floor(this.score))).padStart(8, '0');
    this.printNum(119, MAP_TOP, s);
  }

