// tools/preview.mjs — render game frames to PNG in Node for visual verification.
// Usage: node tools/preview.mjs <frames> [wave] [out.png]
import fs from 'node:fs';
import zlib from 'node:zlib';
import { loadGLB } from '../js/glb.js';
import { Raptor } from '../js/engine.js';

function png(width, height, rgba) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; ihdr[9] = 6; // 8-bit RGBA
  const raw = Buffer.alloc((width * 4 + 1) * height);
  for (let y = 0; y < height; y++) {
    raw[y * (width * 4 + 1)] = 0;
    rgba.copy(raw, y * (width * 4 + 1) + 1, y * width * 4, (y + 1) * width * 4);
  }
  const idat = zlib.deflateSync(raw, { level: 6 });
  const chunk = (type, data) => {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(data.length, 0);
    const td = Buffer.concat([Buffer.from(type), data]);
    const crc = zlib.crc32 ? null : null;
    const c = Buffer.alloc(4);
    // crc32
    let crcVal = 0xffffffff;
    for (const b of td) {
      crcVal ^= b;
      for (let k = 0; k < 8; k++) crcVal = (crcVal >>> 1) ^ (0xedb88320 & -(crcVal & 1));
    }
    c.writeUInt32BE((crcVal ^ 0xffffffff) >>> 0, 0);
    return Buffer.concat([len, td, c]);
  };
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', idat),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

async function main() {
  const frames = parseInt(process.argv[2] || '0', 10);
  const wave = parseInt(process.argv[3] || '0', 10);
  const out = process.argv[4] || 'preview.png';

  const glb0 = await loadGLB('data/FILE0000.GLB');
  const glb1 = await loadGLB('data/FILE0001.GLB');
  const g = new Raptor(glb0, glb1);
  g.init();
  g.startWave(wave);

  // register sounds so engine's playSfx calls are harmless
  g.setAudio({ play: () => false });

  for (let i = 0; i < frames; i++) g.frame();

  // build RGBA from buf + gpal
  const rgba = Buffer.alloc(320 * 200 * 4);
  const pal = g.gpal;
  for (let i = 0; i < 320 * 200; i++) {
    const c = g.buf[i];
    rgba[i * 4] = (pal[c * 3] << 2);
    rgba[i * 4 + 1] = (pal[c * 3 + 1] << 2);
    rgba[i * 4 + 2] = (pal[c * 3 + 2] << 2);
    rgba[i * 4 + 3] = 255;
  }
  fs.writeFileSync(out, png(320, 200, rgba));
  console.log('wrote', out, 'frame', frames, 'wave', wave);
  console.log('score', g.score, 'energy', g.energy, 'ships', g.enemies.length, 'shots', g.shots.length, 'eshots', g.eshots.length);
}

main().catch((e) => { console.error(e); process.exit(1); });

