// engine.js — Faithful JS port of Raptor: Call of the Shadows (sector 1) game logic.
// Ports the C/ASM source in SOURCE/ (RAP.C, TILE.C, ENEMY.C, SHOTS.C, ESHOT.C,
// ANIMS.C, BONUS.C, OBJECTS.C, SHADOWS.C, FLAME.C, GFXAPI) onto a 320x200
// palette-index buffer. Platform-independent; the browser (main.js) drives it.

import {
  SCREENWIDTH, SCREENHEIGHT, EMPTY,
  putImage, putSprite, colorBox, vLine, line,
  drawShadow, putShadeShape, print, makeLightTable,
} from './gfx.js';

// ---------------------------------------------------------------------------
// Constants (from PUBLIC.H / RAPTOR.H / MAP.H / ESHOT.H)
// ---------------------------------------------------------------------------
const MAP_ROWS = 150, MAP_COLS = 9, MAP_ONSCREEN = 8, MAP_BLOCKSIZE = 32;
const MAP_BOTTOM = 182, MAP_TOP = 2, MAP_LEFT = 16, MAP_RIGHT = 304, MAP_SIZE = 1350;
const MAX_SHIELD = 100, MAX_SUPER = 100, SHIELD_COLOR_RUN = 9, SHIELD_LOW = 10;
const PLAYERWIDTH = 32, PLAYERHEIGHT = 32, PLAYERMINX = 5, PLAYERMAXX = 314;
const PLAYERINITX = 144, PLAYERINITY = 160, MINPLAYERY = 0, MAXPLAYERY = 160;
const END_DURATION = 20 * 3, END_EXPLODE = 24, END_FLYOFF = 20 * 2;
const MAX_ADDX = 10, MAX_ADDY = 8;
const MAX_ONSCREEN = 30;
const CHARGE_SHIELD = 24 * 4;

const EB_EASY_LEVEL = 8, EB_MED_LEVEL = 16, EB_HARD_LEVEL = 32, EB_NOT_USED = 64;
const E_EASY_LEVEL = 3, E_MED_LEVEL = 4, E_HARD_LEVEL = 5;

const S_FORWARD_GUNS = 0, S_PLASMA_GUNS = 1, S_MICRO_MISSLE = 2, S_DUMB_MISSLE = 3,
  S_MINI_GUN = 4, S_TURRET = 5, S_MISSLE_PODS = 6, S_AIR_MISSLE = 7, S_GRD_MISSLE = 8,
  S_BOMB = 9, S_ENERGY_GRAB = 10, S_MEGA_BOMB = 11, S_PULSE_CANNON = 12,
  S_FORWARD_LASER = 13, S_DEATH_RAY = 14, S_SUPER_SHIELD = 15, S_ENERGY = 16,
  S_DETECT = 17, S_ITEMBUY1 = 18, S_ITEMBUY2 = 19, S_ITEMBUY3 = 20,
  S_ITEMBUY4 = 21, S_ITEMBUY5 = 22, S_ITEMBUY6 = 23, S_LAST_OBJECT = 24;
const FIRST_SPECIAL = S_DUMB_MISSLE, LAST_WEAPON = S_DEATH_RAY;

const GSPRITE = 0, GPIC = 1;

// Enemy flight types
const F_REPEAT = 0, F_LINEAR = 1, F_KAMI = 2, F_GROUND = 3, F_GROUNDLEFT = 4, F_GROUNDRIGHT = 5;
const GANIM_NORM = 0, GANIM_SHOOT = 1, GANIM_MULTI = 2;
const KAMI_FLY = 0, KAMI_CHASE = 1, KAMI_END = 2;
const E_FORWARD = 0, E_BACKWARD = 1;

// EShot types
const ES_ATPLAYER = 0, ES_ATDOWN = 1, ES_ANGLELEFT = 2, ES_ANGLERIGHT = 3, ES_MISSLE = 4,
  ES_LASER = 5, ES_MINES = 6, ES_PLASMA = 7, ES_COCONUTS = 8;

// EXP types
const EXP_AIRSMALL1 = 0, EXP_AIRMED = 1, EXP_AIRLARGE = 2, EXP_GRDSMALL = 3, EXP_GRDMED = 4,
  EXP_GRDLARGE = 5, EXP_BOSS = 6, EXP_PERSON = 7, EXP_ENERGY = 8, EXP_PLATOON = 9, EXP_AIRSMALL2 = 10;

// Anim handles (ANIMS_Init order)
const A_LARGE_GROUND_EXPLO1 = 0, A_SMALL_GROUND_EXPLO = 1, A_PERSON = 2, A_PLATOON = 3,
  A_LARGE_AIR_EXPLO = 4, A_MED_AIR_EXPLO = 5, A_SMALL_AIR_EXPLO = 6, A_MED_AIR_EXPLO2 = 7,
  A_ENERGY_AIR_EXPLO = 8, A_LASER_BLAST = 9, A_SMALL_SMOKE = 10, A_SMALL_SMOKE_DOWN = 11,
  A_SMALL_SMOKE_UP = 12, A_ENERGY_GRAB_HIT = 13, A_BLUE_SPARK = 14, A_ORANGE_SPARK = 15,
  A_PLAYER_SHOOT = 16, A_GROUND_FLARE = 17, A_GROUND_SPARKLE = 18, A_ENERGY_GRAB = 19, A_SUPER_SHIELD = 20;

const NORM_SHOOT = -1, START_SHOOT = 0;

// ---------------------------------------------------------------------------
// Watcom C rand() — the game seeds with srand(1024 * wave) so wave-1's random
// sequence is deterministic. Reproducing it makes gameplay (and M1) faithful.
// ---------------------------------------------------------------------------
export class Rand {
  constructor(seed) { this.state = seed >>> 0; }
  next() {
    this.state = (Math.imul(this.state, 0x015a4e35) + 1) >>> 0;
    return (this.state >> 16) & 0x7fff;
  }
  random(n) { return this.next() % n; }
}

// ---------------------------------------------------------------------------
// Assets
// ---------------------------------------------------------------------------
export class Assets {
  // glbs: { file0: GLBFile, file1: GLBFile }
  constructor(glb0, glb1) {
    this.glb = [glb0, glb1];
    this.cache = new Map();
    this.spriteLibs = [];
  }
  resolve(name) {
    const idx = name.indexOf('_');
    if (idx < 0) return null;
    const num = parseInt(name.slice(idx + 1).match(/^\d+/)?.[0], 10);
    return num == null ? null : num;
  }
  // Raptor uses DWORD handles (filenum<<16 | itemnum). Names carry the file.
  item(name) {
    if (!this.cache.has(name)) {
      const f = name[4] === '0' ? 0 : 1;
      this.cache.set(name, this.glb[f].raw(name));
    }
    return this.cache.get(name);
  }
}

// ---------------------------------------------------------------------------
// SPRITE (enemy library) parser — 528-byte structs. In this build BOOL is 4 bytes:
//   iname[16]; item; bonus; exptype; shotspace; ground(4); suck(4); frame_rate;
//   num_frames; countdown; rewind; animtype; shadow(4); bossflag; hits; money;
//   shootstart; shootcnt; shootframe; movespeed; numflight; repos; flighttype;
//   numguns; numengs; sfx; song; then 6x SHORT[24]; then 2x SHORT[30].
// ---------------------------------------------------------------------------
const SPRITE_SIZE = 528;
const SROFS = {
  iname: 0, item: 16, bonus: 20, exptype: 24, shotspace: 28, ground: 32, suck: 36,
  frame_rate: 40, num_frames: 44, countdown: 48, rewind: 52, animtype: 56, shadow: 60,
  bossflag: 64, hits: 68, money: 72, shootstart: 76, shootcnt: 80, shootframe: 84,
  movespeed: 88, numflight: 92, repos: 96, flighttype: 100, numguns: 104, numengs: 108,
  sfx: 112, song: 116, shoot_type: 120, engx: 168, engy: 216, englx: 264, shootx: 312,
  shooty: 360, flightx: 408, flighty: 468,
};
function parseSpriteLib(data) {
  const v = new DataView(data.buffer, data.byteOffset, data.byteLength);
  const out = [];
  const n = Math.floor(data.length / SPRITE_SIZE);
  for (let i = 0; i < n; i++) {
    const o = i * SPRITE_SIZE;
    const s = {
      iname: '', item: 0, bonus: 0, exptype: 0, shotspace: 0, ground: 0, suck: 0,
      frame_rate: 0, num_frames: 0, countdown: 0, rewind: 0, animtype: 0, shadow: 0,
      bossflag: 0, hits: 0, money: 0, shootstart: 0, shootcnt: 0, shootframe: 0,
      movespeed: 0, numflight: 0, repos: 0, flighttype: 0, numguns: 0, numengs: 0,
      sfx: 0, song: 0,
      shoot_type: [], engx: [], engy: [], englx: [], shootx: [], shooty: [], flightx: [], flighty: [],
    };
    let nm = '';
    for (let c = 0; c < 16; c++) {
      const ch = data[o + c];
      if (ch === 0) break;
      nm += String.fromCharCode(ch);
    }
    s.iname = nm;
    s.item = v.getInt32(o + SROFS.item, true);
    s.bonus = v.getInt32(o + SROFS.bonus, true);
    s.exptype = v.getInt32(o + SROFS.exptype, true);
    s.shotspace = v.getInt32(o + SROFS.shotspace, true);
    s.ground = v.getInt32(o + SROFS.ground, true);
    s.suck = v.getInt32(o + SROFS.suck, true);
    s.frame_rate = v.getInt32(o + SROFS.frame_rate, true);
    s.num_frames = v.getInt32(o + SROFS.num_frames, true);
    s.countdown = v.getInt32(o + SROFS.countdown, true);
    s.rewind = v.getInt32(o + SROFS.rewind, true);
    s.animtype = v.getInt32(o + SROFS.animtype, true);
    s.shadow = v.getInt32(o + SROFS.shadow, true);
    s.bossflag = v.getInt32(o + SROFS.bossflag, true);
    s.hits = v.getInt32(o + SROFS.hits, true);
    s.money = v.getInt32(o + SROFS.money, true);
    s.shootstart = v.getInt32(o + SROFS.shootstart, true);
    s.shootcnt = v.getInt32(o + SROFS.shootcnt, true);
    s.shootframe = v.getInt32(o + SROFS.shootframe, true);
    s.movespeed = v.getInt32(o + SROFS.movespeed, true);
    s.numflight = v.getInt32(o + SROFS.numflight, true);
    s.repos = v.getInt32(o + SROFS.repos, true);
    s.flighttype = v.getInt32(o + SROFS.flighttype, true);
    s.numguns = v.getInt32(o + SROFS.numguns, true);
    s.numengs = v.getInt32(o + SROFS.numengs, true);
    s.sfx = v.getInt32(o + SROFS.sfx, true);
    s.song = v.getInt32(o + SROFS.song, true);
    const rd = (off, cnt) => { const a = []; for (let k = 0; k < cnt; k++) a.push(v.getInt16(o + off + k * 2, true)); return a; };
    s.shoot_type = rd(SROFS.shoot_type, 24);
    s.engx = rd(SROFS.engx, 24);
    s.engy = rd(SROFS.engy, 24);
    s.englx = rd(SROFS.englx, 24);
    s.shootx = rd(SROFS.shootx, 24);
    s.shooty = rd(SROFS.shooty, 24);
    s.flightx = rd(SROFS.flightx, 30);
    s.flighty = rd(SROFS.flighty, 30);
    out.push(s);
  }
  return out;
}

