          remove = true;
          this.subEnergy(lib.hits, 'eshot');
        }
      }
      if (remove) { this.eshots.splice(i, 1); i--; continue; }
      shot.cnt++;
      if (lib.smokeflag && shot.cnt & 1) {
        this.startAAnim(A_SMALL_SMOKE_UP, shot.x + lib.xoff, shot.y);
      }
    }
  }

