    // move up
    if (s.speed < 16) s.speed++;
    s.curframe++;
    if (s.curframe >= 4) s.curframe = 0;
    s.move.y -= s.speed;
    s.x = s.move.x;
    s.y = s.move.y;
    if (s.y < 0 || s.y > 200) { this.shots.splice(si, 1); si--; continue; }
    // hit test
    if (this.enemyDamageAll(s.x, s.y, 1)) {
      if (this.rand.random(2)) this.startAnim(A_BLUE_SPARK, s.x, s.y);
      else this.startAnim(A_ORANGE_SPARK, s.x, s.y);
      this.shots.splice(si, 1); si--;
      continue;
    }
    if (this.tileIsHit(1, s.x, s.y)) { this.shots.splice(si, 1); si--; continue; }
  }
