// audio.js — Web Audio playback of Raptor's digital SFX.
//
// Sound items in FILE0000.GLB are stored as:
//   byte 0  = 3 (digital flag)
//   byte 1  = 0
//   bytes 2-3 = sample rate (LE, 11025)
//   bytes 4-7 = sample count (LE)
//   then raw 8-bit unsigned PCM
// Other formats (0=PC speaker, 1=MIDI, 2=Roland) are skipped.

export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.sounds = new Map(); // name -> AudioBuffer
    this._pending = [];
    this.sfxCount = 0;
  }

  ensure() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.5;
      this.master.connect(this.ctx.destination);
      this.buildBuffers();
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
    return this.ctx;
  }

  // Register a raw GLB sound item payload.
  register(name, data) {
    if (data.length < 8 || data[0] !== 3) return;
    const v = new DataView(data.buffer, data.byteOffset, data.byteLength);
    const rate = v.getUint16(2, true);
    const len = v.getUint32(4, true);
    if (rate < 1000 || rate > 48000 || len <= 0) return;
    const pcm = data.subarray(8, 8 + len);
    this._pending.push({ name, rate, pcm });
  }

  contextState() {
    return this.ctx ? this.ctx.state : 'suspended';
  }

  unlock() {
    this.ensure();
  }

  buildBuffers() {
    if (!this.ctx) return;
    for (const { name, rate, pcm } of this._pending) {
      const buf = this.ctx.createBuffer(1, pcm.length, rate);
      const ch = buf.getChannelData(0);
      for (let i = 0; i < pcm.length; i++) ch[i] = (pcm[i] - 128) / 128;
      this.sounds.set(name, buf);
    }
    this._pending = [];
  }

  // Play a sound by GLB item name. `volume` 0..1. Returns true if started.
  play(name, volume) {
    if (!this.ctx) return false;
    const buf = this.sounds.get(name);
    if (!buf) return false;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const g = this.ctx.createGain();
    g.gain.value = volume == null ? 1 : Math.max(0, Math.min(1, volume));
    src.connect(g).connect(this.master);
    src.start();
    this.sfxCount++;
    return true;
  }
}

